/// <summary>
/// PaffH 02.05.22
/// </summary>
/// <param name = "_forUpdate">boolean</param>
/// <param name = "_concurrencyModel">ConcurrencyModel</param>
/// <returns>NDXProdIdentUKParameters</returns>
public static NDXProdIdentUKParameters find( boolean _forUpdate = false,
                                    ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
{
    NDXProdIdentUKParameters parameters;
    parameters.selectForUpdate(_forUpdate);

    if (_forUpdate && _concurrencyModel != ConcurrencyModel::Auto)
    {
        parameters.concurrencyModel(_concurrencyModel);
    }

    select firstonly parameters
        index Key
        where parameters.Key == 0;

    if (!parameters)
    {
        Company::createParameter(parameters);
    }

    return parameters;
}

/// <summary>
/// PaffH 02.05.22
/// unique prefix for BT record
/// </summary>
/// <returns>NDXBTRecordIdPrefix</returns>
public NDXBTRecordIdPrefix BTRecordIdPrefix()
{
    if (this.BTRecordIdPrefix)
    {
        return this.BTRecordIdPrefix;
    }
    else
    {
        return strFmt('%1_%2', NDXEnvironmentInfoParameters::find().Id, curExt());
    }
}
